document.addEventListener('DOMContentLoaded',function(){initBokehEffect();initPillNavigation();initSpotlightCards();initHamburgerMenu();var tooltipTriggerList = [].slice.call(document.querySelectorAll('[data-bs-toggle="tooltip"]'));var tooltipList = tooltipTriggerList.map(function(tooltipTriggerEl){return new bootstrap.Tooltip(tooltipTriggerEl)});var popoverTriggerList = [].slice.call(document.querySelectorAll('[data-bs-toggle="popover"]'));var popoverList = popoverTriggerList.map(function(popoverTriggerEl){return new bootstrap.Popover(popoverTriggerEl)});const fadeElements = document.querySelectorAll('.fade-in');fadeElements.forEach(element =>{element.style.opacity = '0';element.style.transform = 'translateY(20px)';setTimeout(()=>{element.style.transition = 'opacity 0.5s ease,transform 0.5s ease';element.style.opacity = '1';element.style.transform = 'translateY(0)'},100)});const alerts = document.querySelectorAll('.alert');alerts.forEach(alert =>{if(!alert.classList.contains('alert-permanent')){setTimeout(()=>{const bsAlert = new bootstrap.Alert(alert);bsAlert.close()},5000)}})});class ChatInterface{constructor(chatContainer,inputField,sendButton){this.chatContainer = chatContainer;this.inputField = inputField;this.sendButton = sendButton;this.isTyping = false;this.init()}init(){if(this.sendButton){this.sendButton.addEventListener('click',()=> this.sendMessage())}if(this.inputField){this.inputField.addEventListener('keypress',(e)=>{if(e.key === 'Enter' && !e.shiftKey){e.preventDefault();this.sendMessage()}})}}sendMessage(){const message = this.inputField.value.trim();if(message && !this.isTyping){this.addMessage(message,'user');this.inputField.value = '';this.simulateTyping();this.sendToBackend(message)}}addMessage(message,sender){const messageDiv = document.createElement('div');messageDiv.className = `message ${sender}`;messageDiv.textContent = message;this.chatContainer.appendChild(messageDiv);this.scrollToBottom()}simulateTyping(){this.isTyping = true;this.sendButton.disabled = true;const typingDiv = document.createElement('div');typingDiv.className = 'message bot typing';typingDiv.innerHTML = 'AI is typing<span class="typing-dots">...</span>';typingDiv.id = 'typing-indicator';this.chatContainer.appendChild(typingDiv);this.scrollToBottom()}stopTyping(){this.isTyping = false;this.sendButton.disabled = false;const typingIndicator = document.getElementById('typing-indicator');if(typingIndicator){typingIndicator.remove()}}sendToBackend(message){setTimeout(()=>{this.stopTyping();this.addMessage(this.generateResponse(message),'bot')},1500)}generateResponse(message){const responses = [ "I understand you're going through a difficult time. Can you tell me more about what's bothering you?","Thank you for sharing that with me. Have you considered speaking with a counselor about this?","It's completely normal to feel overwhelmed sometimes. Here are some coping strategies that might help...","I'm here to support you. Would you like me to help you schedule an appointment with a professional?","That sounds challenging. Remember that seeking help is a sign of strength,not weakness." ];return responses[Math.floor(Math.random()* responses.length)]}scrollToBottom(){this.chatContainer.scrollTop = this.chatContainer.scrollHeight}}class AppointmentBooking{constructor(){this.selectedSlot = null;this.init()}init(){const slots = document.querySelectorAll('.appointment-slot');slots.forEach(slot =>{slot.addEventListener('click',()=> this.selectSlot(slot))});this.initCalendar()}selectSlot(slot){if(this.selectedSlot){this.selectedSlot.classList.remove('selected')}this.selectedSlot = slot;slot.classList.add('selected');const bookButton = document.getElementById('book-appointment-btn');if(bookButton){bookButton.disabled = false}}initCalendar(){}}function validateForm(formId){const form = document.getElementById(formId);if(!form)return false;const requiredFields = form.querySelectorAll('[required]');let isValid = true;requiredFields.forEach(field =>{if(!field.value.trim()){field.classList.add('is-invalid');isValid = false}else{field.classList.remove('is-invalid')}});return isValid}function showLoading(element){element.innerHTML = '<div class="spinner"></div>';element.disabled = true}function hideLoading(element,originalContent){element.innerHTML = originalContent;element.disabled = false}function showEmergencyModal(){const modal = new bootstrap.Modal(document.getElementById('emergencyModal'));modal.show()}function formatDate(date){return new Date(date).toLocaleDateString('en-US',{year:'numeric',month:'long',day:'numeric'})}function formatTime(time){return new Date(`2000-01-01T${time}`).toLocaleTimeString('en-US',{hour:'2-digit',minute:'2-digit'})}function initPillNavigation(){const pillLinks = document.querySelectorAll('.pill-link');const currentPath = window.location.pathname;pillLinks.forEach(link =>{const linkPath = new URL(link.href).pathname;if(currentPath === linkPath ||(linkPath !== '/' && currentPath.includes(linkPath.split('/')[1]))){link.classList.add('current-page')}link.addEventListener('click',function(e){pillLinks.forEach(l => l.classList.remove('current-page'));this.classList.add('current-page');this.style.transform = 'scale(0.95)';setTimeout(()=>{this.style.transform = ''},150)});link.addEventListener('mouseenter',function(){this.style.transform = 'translateY(-2px)scale(1.02)'});link.addEventListener('mouseleave',function(){if(!this.classList.contains('current-page')){this.style.transform = ''}})});if(currentPath === '/' || currentPath === '/en/' || currentPath === '/hi/' || currentPath.match(/^\/(en|hi|ta|bn|mr|gu|kn|ml|pa|te)\/?$/)){const homeLink = document.querySelector('.pill-link[data-page="home"]');if(homeLink){pillLinks.forEach(l => l.classList.remove('current-page'));homeLink.classList.add('current-page')}}}class SpotlightCards{constructor(){this.cards = document.querySelectorAll('.spotlight-card');this.init()}init(){this.cards.forEach((card,index)=>{this.setupCardEvents(card,index)});this.setupScrollAnimations()}setupCardEvents(card,index){card.addEventListener('mousemove',(e)=>{this.updateSpotlight(card,e)});card.addEventListener('mouseleave',()=>{this.resetSpotlight(card)});card.addEventListener('click',(e)=>{if(!e.target.matches('a,button,.spotlight-btn')){this.animateClick(card)}});card.style.animationDelay = `${index * 0.1}s`}updateSpotlight(card,event){const rect = card.getBoundingClientRect();const x = event.clientX - rect.left;const y = event.clientY - rect.top;const centerX = rect.width / 2;const centerY = rect.height / 2;const deltaX =(x - centerX)/ centerX;const deltaY =(y - centerY)/ centerY;const spotlight = card.querySelector('::before')|| card;card.style.setProperty('--spotlight-x',`${x}px`);card.style.setProperty('--spotlight-y',`${y}px`);const tiltX = deltaY * 5;const tiltY = deltaX * -5;card.style.transform = `perspective(1000px)rotateX(${tiltX}deg)rotateY(${tiltY}deg)translateY(-8px)scale(1.02)`}resetSpotlight(card){card.style.transform = ''}animateClick(card){card.style.transform = 'scale(0.95)';setTimeout(()=>{card.style.transform = ''},150)}setupScrollAnimations(){if('IntersectionObserver' in window){const observer = new IntersectionObserver((entries)=>{entries.forEach((entry)=>{if(entry.isIntersecting){entry.target.classList.add('fade-in');observer.unobserve(entry.target)}})},{threshold:0.1,rootMargin:'50px'});this.cards.forEach((card)=>{observer.observe(card)})}}addCard(cardElement){this.setupCardEvents(cardElement,this.cards.length);this.cards.push(cardElement)}}function initBokehEffect(){const bokehContainer = document.querySelector('.bokeh-container');if(!bokehContainer)return;const lights = document.querySelectorAll('.bokeh-light');lights.forEach((light,index)=>{const randomLeft = Math.random()* 100;light.style.left = randomLeft + '%';const drift =(Math.random()- 0.5)* 30;light.style.setProperty('--drift',drift + 'px');const baseOpacity = 0.4 +(Math.random()* 0.6);light.style.setProperty('--base-opacity',baseOpacity)});let lightCounter = 10;setInterval(()=>{if(document.querySelectorAll('.bokeh-light').length < 20){createFloatingLight(lightCounter++)}},5000)}function createFloatingLight(id){const bokehContainer = document.querySelector('.bokeh-container');if(!bokehContainer)return;const light = document.createElement('div');light.className = 'bokeh-light';light.id = `dynamic-light-${id}`;const size = 4 + Math.random()* 12;const left = Math.random()* 100;const duration = 15 + Math.random()* 10;const delay = Math.random()* 5;const colors = [ 'rgba(255,248,220,0.8)','rgba(173,216,230,0.6)','rgba(255,255,255,0.9)','rgba(255,223,186,0.7)','rgba(176,196,222,0.5)','rgba(255,250,205,0.8)',];const color = colors[Math.floor(Math.random()* colors.length)];light.style.cssText = ` width:${size}px;height:${size}px;left:${left}%;background:radial-gradient(circle,${color}0%,${color.replace('0.','0.1')}70%,transparent 100%);animation:floatAndFade ${duration}s infinite linear;animation-delay:-${delay}s;filter:blur(${2 + Math.random()* 2}px);`;bokehContainer.appendChild(light);setTimeout(()=>{if(light.parentNode){light.parentNode.removeChild(light)}},duration * 1000)}function initSpotlightCards(){if(document.querySelector('.spotlight-card')){return new SpotlightCards()}return null}class HamburgerMenu{constructor(){this.hamburgerButton = document.getElementById('hamburgerMenu');this.desktopMenuButton = document.getElementById('desktopMenuButton');this.drawer = document.getElementById('slidingDrawer');this.overlay = document.getElementById('drawerOverlay');this.menuItems = document.querySelectorAll('.drawer-menu-item');this.isOpen = false;this.init()}init(){if(!this.drawer || !this.overlay){return}if(this.hamburgerButton){this.hamburgerButton.addEventListener('click',(e)=>{e.stopPropagation();this.toggle()})}if(this.desktopMenuButton){this.desktopMenuButton.addEventListener('click',(e)=>{e.stopPropagation();this.toggle()})}this.overlay.addEventListener('click',()=>{this.close()});document.addEventListener('click',(e)=>{if(this.isOpen && !this.drawer.contains(e.target)&& !(this.hamburgerButton && this.hamburgerButton.contains(e.target))&& !(this.desktopMenuButton && this.desktopMenuButton.contains(e.target))){this.close()}});this.menuItems.forEach(item =>{item.addEventListener('click',()=>{setTimeout(()=>{this.close()},150)})});document.addEventListener('keydown',(e)=>{if(e.key === 'Escape' && this.isOpen){this.close()}});this.setupScrollLock()}toggle(){if(this.isOpen){this.close()}else{this.open()}}open(){this.isOpen = true;if(this.hamburgerButton){this.hamburgerButton.classList.add('active')}if(this.desktopMenuButton){this.desktopMenuButton.classList.add('active')}this.drawer.classList.add('active');this.overlay.classList.add('active');document.body.style.overflow = 'hidden';this.animateMenuItems('in');setTimeout(()=>{const firstMenuItem = this.drawer.querySelector('.drawer-menu-item');if(firstMenuItem){firstMenuItem.focus()}},400)}close(){this.isOpen = false;if(this.hamburgerButton){this.hamburgerButton.classList.remove('active')}if(this.desktopMenuButton){this.desktopMenuButton.classList.remove('active')}this.drawer.classList.remove('active');this.overlay.classList.remove('active');document.body.style.overflow = '';this.animateMenuItems('out')}animateMenuItems(direction){this.menuItems.forEach((item,index)=>{if(direction === 'in'){item.style.transform = 'translateX(-30px)';item.style.opacity = '0';setTimeout(()=>{item.style.transition = 'all 0.3s cubic-bezier(0.25,0.8,0.25,1)';item.style.transform = 'translateX(0)';item.style.opacity = '1'},index * 50 + 200);setTimeout(()=>{item.style.transition = ''},index * 50 + 500)}else{item.style.transform = 'translateX(-30px)';item.style.opacity = '0';setTimeout(()=>{item.style.transform = '';item.style.opacity = ''},400)}})}setupScrollLock(){this.originalOverflow = document.body.style.overflow;let startY = 0;const preventScroll =(e)=>{if(this.isOpen){const currentY = e.touches[0].clientY;if(e.type === 'touchstart'){startY = currentY}else if(e.type === 'touchmove'){if(!this.drawer.contains(e.target)){e.preventDefault()}}}};document.addEventListener('touchstart',preventScroll,{passive:false});document.addEventListener('touchmove',preventScroll,{passive:false})}}function initHamburgerMenu(){return new HamburgerMenu()}window.ChatInterface = ChatInterface;window.AppointmentBooking = AppointmentBooking;window.SpotlightCards = SpotlightCards;window.HamburgerMenu = HamburgerMenu;window.validateForm = validateForm;window.showLoading = showLoading;window.hideLoading = hideLoading;window.showEmergencyModal = showEmergencyModal;window.formatDate = formatDate;window.formatTime = formatTime;window.initPillNavigation = initPillNavigation;window.initSpotlightCards = initSpotlightCards;window.initBokehEffect = initBokehEffect;window.initHamburgerMenu = initHamburgerMenu;